create or replace function confirmar_atendimento_realizado(p_appointment_id uuid, p_data date, p_actor uuid) returns void language plpgsql security definer set search_path = public as $$ declare a appointments%rowtype; k text; d date; begin select * into a from appointments where id = p_appointment_id for update; if not found then raise exception 'atendimento inexistente'; end if; if a.anulado_em is not null then raise exception 'atendimento anulado não pode ser confirmado'; end if; if p_data is null then raise exception 'data exata do atendimento é obrigatória'; end if; if p_data > (now() at time zone 'America/Sao_Paulo')::date then raise exception 'data no futuro'; end if; update appointments set status = 'completed', completed_at = coalesce(completed_at, now()), data_realizada = p_data, data_status = 'exata', realizado_confirmado_em = coalesce(realizado_confirmado_em, now()), realizado_confirmado_por = coalesce(realizado_confirmado_por, p_actor) where id = a.id; foreach k in array array['d30','d90','m6'] loop d := case k when 'd30' then p_data + 30 when 'd90' then p_data + 90 else p_data + 180 end; insert into follow_up_milestones (organization_id, appointment_id, patient_id, kind, due_original, due_current) values (a.organization_id, a.id, a.patient_id, k, d, d) on conflict (appointment_id, kind) do update set due_original = excluded.due_original, due_current = excluded.due_current, updated_at = now() where follow_up_milestones.status = 'previsto' and follow_up_milestones.due_original <> excluded.due_original and not exists (select 1 from event_links el where el.milestone_id = follow_up_milestones.id); end loop; end $$;
revoke all on function confirmar_atendimento_realizado(uuid, date, uuid) from public, anon, authenticated;
grant execute on function confirmar_atendimento_realizado(uuid, date, uuid) to service_role;
update follow_up_milestones m set due_original = a.data_realizada + 180, due_current = a.data_realizada + 180, updated_at = now() from appointments a where a.id = m.appointment_id and m.kind = 'm6' and m.status = 'previsto' and m.due_current = m.due_original and a.data_realizada is not null and m.due_original = (a.data_realizada + interval '6 months')::date and m.due_original <> a.data_realizada + 180 and a.data_realizada + 180 >= (now() at time zone 'America/Sao_Paulo')::date and not exists (select 1 from event_links el where el.milestone_id = m.id);
